try:
    print('>>> x = range(0)')
    print('>>> y = (1, 2)')
    print('>>> x &= y')
    print('>>> x')
    x = range(0)
    y = (1, 2)
    x &= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
